    public void testBuilder() {
        Base16InputStream.Builder builder = Base16InputStream.builder();
        assertTrue(builder instanceof Base16InputStream.Builder);
    }

    @Test
    public void testConstructorWithInputStream() {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input);
        assertTrue(stream instanceof Base16InputStream);
    }

