    public void testReadSingleByte() throws IOException {
        byte[] inputBytes = {0x01};
        InputStream input = new ByteArrayInputStream(inputBytes);
        Base16InputStream stream = new Base16InputStream(input);
        byte[] output = new byte[2];
        int read = stream.read(output, 0, 2);
        assertEquals(2, read);
        assertArrayEquals(new byte[]{0x30, 0x31}, output);
    }

