        byte[] inputBytes = {0x01, 0x02, 0x03};
        InputStream input = new ByteArrayInputStream(inputBytes);
        Base16InputStream stream = new Base16InputStream(input);
        byte[] output = new byte[6];
        int read = stream.read(output, 0, 6);
        assertEquals(6, read);
        assertArrayEquals(new byte[]{0x30, 0x31, 0x30, 0x32, 0x30, 0x33}, output);
    }

    @Test
    public void testReadWithEncoding() throws IOException {
        byte[] inputBytes = {0x30, 0x31, 0x30, 0x32};
        InputStream input = new ByteArrayInputStream(inputBytes);
        Base16InputStream stream = new Base16InputStream(input, true);
        byte[] output = new byte[2];
        int read = stream.read(output, 0, 2);
        assertEquals(2, read);
        assertArrayEquals(new byte[]{0x01, 0x02}, output);
    }

    @Test
