package org.apache.commons.codec.binary;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import org.apache.commons.codec.CodecPolicy;
import org.junit.Test;

public class Base16InputStreamTest {

    @Test
    public void testBuilder() {
        Base16InputStream.Builder builder = Base16InputStream.builder();
        assertTrue(builder instanceof Base16InputStream.Builder);
    }

    @Test
    public void testConstructorWithInputStream() {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input);
        assertTrue(stream instanceof Base16InputStream);
    }

    @Test
    public void testConstructorWithInputStreamAndEncode() {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input, false);
        assertTrue(stream instanceof Base16InputStream);
    }

    @Test
    public void testConstructorWithInputStreamEncodeAndLowerCase() {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input, false, true);
        assertTrue(stream instanceof Base16InputStream);
    }

    @Test
    public void testConstructorWithInputStreamEncodeLowerCaseAndPolicy() {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input, false, true, CodecPolicy.STRICT);
        assertTrue(stream instanceof Base16InputStream);
    }

    @Test
    public void testReadEmptyStream() throws IOException {
        InputStream input = new ByteArrayInputStream(new byte[]{});
        Base16InputStream stream = new Base16InputStream(input);
        assertEquals(-1, stream.read());
    }

    @Test
    public void testReadSingleByte() throws IOException {
        byte[] inputBytes = {0x01};
        InputStream input = new ByteArrayInputStream(inputBytes);
        Base16InputStream stream = new Base16InputStream(input);
        byte[] output = new byte[2];
        int read = stream.read(output, 0, 2);
        assertEquals(2, read);
        assertArrayEquals(new byte[]{0x30, 0x31}, output);
    }

    @Test
    public void testReadMultipleBytes() throws IOException {
        byte[] inputBytes = {0x01, 0x02, 0x03};
        InputStream input = new ByteArrayInputStream(inputBytes);
        Base16InputStream stream = new Base16InputStream(input);
        byte[] output = new byte[6];
