package org.apache.commons.codec.binary;

import org.apache.commons.codec.CodecPolicy;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base32Test {

    @Test
    public void testBuilderDefault() {
        Base32 base32 = Base32.builder().get();
        assertNotNull(base32);
        assertEquals(0, base32.getLineLength());
        assertArrayEquals(Base32.CHUNK_SEPARATOR, base32.getLineSeparator());
        assertEquals('=', base32.getPadding());
        assertEquals(CodecPolicy.LENIENT, base32.getCodecPolicy());
    }

    @Test
    public void testBuilderWithParameters() {
        Base32 base32 = Base32.builder()
                .setLineLength(76)
                .setLineSeparator('\r', '\n')
                .setPadding('*')
                .setDecodingPolicy(CodecPolicy.STRICT)
                .get();

        assertNotNull(base32);
        assertEquals(76, base32.getLineLength());
        assertArrayEquals(new byte[]{'\r', '\n'}, base32.getLineSeparator());
        assertEquals('*', base32.getPadding());
        assertEquals(CodecPolicy.STRICT, base32.getCodecPolicy());
    }

    @Test
    public void testEncodeDecode() {
        Base32 base32 = Base32.builder().get();
        byte[] original = "Hello World".getBytes();
        byte[] encoded = base32.encode(original);
        byte[] decoded = base32.decode(encoded);
        assertArrayEquals(original, decoded);
    }

    @Test
    public void testEncodeDecodeWithPadding() {
        Base32 base32 = Base32.builder().setPadding('*').get();
        byte[] original = "Hello World".getBytes();
        byte[] encoded = base32.encode(original);
        byte[] decoded = base32.decode(encoded);
        assertArrayEquals(original, decoded);
    }

    @Test
    public void testEncodeDecodeWithLineLength() {
        Base32 base32 = Base32.builder().setLineLength(20).get();
        byte[] original = "Hello World".getBytes();
        byte[] encoded = base32.encode(original);
        byte[] decoded = base32.decode(encoded);
        assertArrayEquals(original, decoded);
    }

    @Test
    public void testEncodeDecodeWithHex() {
        Base32 base32 = Base32.builder().setHexEncodeTable(true).get();
        byte[] original = "Hello World".getBytes();
        byte[] encoded = base32.encode(original);
        byte[] decoded = base32.decode(encoded);
        assertArrayEquals(original, decoded);
    }

    @Test
    public void testEmptyInput() {
        Base32 base32 = Base32.builder().get();
        byte[] empty = new byte[0];
        byte[] encoded = base32.encode(empty);
        byte[] decoded = base32.decode(encoded);
        assertArrayEquals(empty, decoded);
    }

    @Test
    public void testIsInAlphabet() {
        Base32 base32 = Base32.builder().get();
        assertTrue(base32.isInAlphabet((byte) 'A'));
        assertTrue(base32.isInAlphabet((byte) 'Z'));
        assertTrue(base32.isInAlphabet((byte) '2'));
        assertTrue(base32.isInAlphabet((byte) '7'));
        assertFalse(base32.isInAlphabet((byte) 'a'));
        assertFalse(base32.isInAlphabet((byte) 'b'));
        assertFalse(base32.isInAlphabet((byte) '1'));
        assertFalse(base32.isInAlphabet((byte) '8'));
    }

    @Test
    public void testStrictDecoding() {
        Base32 base32 = Base32.builder().setDecodingPolicy(CodecPolicy.STRICT).get();
        byte[] invalidInput = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567".getBytes();
        try {
            base32.decode(invalidInput);
            fail("Expected IllegalArgumentException for invalid input with strict decoding");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Last encoded character(s)"));
        }
    }

