                        buffer[context.pos++] = (byte) (context.lbitWorkArea >> 16 & MASK_8BITS);

                        buffer[context.pos++] = (byte) (context.lbitWorkArea >> 8 & MASK_8BITS);

                        buffer[context.pos++] = (byte) (context.lbitWorkArea & MASK_8BITS);

