package org.apache.commons.codec.binary;

import org.apache.commons.codec.CodecPolicy;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base32Test {

    @Test
    public void testBuilderDefault() {
        Base32 base32 = Base32.builder().get();
        assertNotNull(base32);
        assertEquals(0, base32.getLineLength());
        assertArrayEquals(Base32.CHUNK_SEPARATOR, base32.getLineSeparator());
        assertEquals('=', base32.getPadding());
        assertEquals(CodecPolicy.LENIENT, base32.getCodecPolicy());
    }

