            this.encodeSize = BYTES_PER_ENCODED_BLOCK + lineSeparator.length;

            this.lineSeparator = lineSeparator;

        } else {

            this.encodeSize = BYTES_PER_ENCODED_BLOCK;

            this.lineSeparator = null;

