        if (context.eof) {

            return;

        }

        if (length < 0) {

            context.eof = true;

            final byte[] accumulate = context.buffer = context.buffer != null ? context.buffer : EMPTY_BYTE_ARRAY;

            if (accumulate.length > 0) {

