                    // top 6 bits:

                    buffer[context.pos++] = encodeTable[context.ibitWorkArea >> 2 & MASK_6_BITS];

                    // remaining 2:

                    buffer[context.pos++] = encodeTable[context.ibitWorkArea << 4 & MASK_6_BITS];

