        final int loopEnd = end - 1;

        while (offset < loopEnd) {

            result = decodeOctet(data[offset++]) << BITS_PER_ENCODED_BYTE;

            result |= decodeOctet(data[offset++]);

            buffer[context.pos++] = (byte) result;

        }

        // we have one char of a hex-pair left over

        if (offset < end) {

