package org.apache.commons.codec.binary;

import static org.apache.commons.codec.binary.BaseNCodec.EOF;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

import org.junit.Test;
import static org.junit.Assert.*;

public class BaseNCodecInputStreamTest {

    @Test
    public void testConstructorWithBuilder() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(Base16InputStream.builder().setInputStream(new ByteArrayInputStream(new byte[0])));
        assertNotNull(stream);
    }

    @Test
    public void testConstructorWithParameters() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(new ByteArrayInputStream(new byte[0]), new Base16(), false);
        assertNotNull(stream);
    }

    @Test
    public void testAvailable() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        assertEquals(1, stream.available());
        input.close();
    }

    @Test
    public void testIsStrictDecoding() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(new ByteArrayInputStream(new byte[0]), new Base16(), false);
        assertFalse(stream.isStrictDecoding());
        stream.close();
    }

    @Test
    public void testMarkSupported() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(new ByteArrayInputStream(new byte[0]), new Base16(), false);
        assertFalse(stream.markSupported());
        stream.close();
    }

    @Test
    public void testReadSingleByte() throws Exception {
        byte[] data = {0x31, 0x32, 0x33}; // "123"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        assertEquals('1', stream.read());
        assertEquals('2', stream.read());
        assertEquals('3', stream.read());
        assertEquals(EOF, stream.read());
        stream.close();
    }

    @Test
    public void testReadMultipleBytes() throws Exception {
        byte[] data = {0x31, 0x32, 0x33}; // "123"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        byte[] buffer = new byte[3];
        int read = stream.read(buffer, 0, 3);
        assertEquals(3, read);
        assertArrayEquals(data, buffer);
        stream.close();
    }

    @Test
    public void testReadWithOffsetAndLength() throws Exception {
        byte[] data = {0x31, 0x32, 0x33, 0x34, 0x35}; // "12345"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        byte[] buffer = new byte[5];
        int read = stream.read(buffer, 1, 3);
        assertEquals(3, read);
        assertArrayEquals(new byte[]{0, 0x32, 0x33, 0x34, 0}, buffer);
        stream.close();
    }

    @Test(expected = NullPointerException.class)
    public void testReadWithNullArray() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        stream.read(null, 0, 0);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadWithInvalidOffset() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, -1, 10);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadWithInvalidLength() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, 0, -1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadWithInvalidBufferSize() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, 5, 6);
    }

    @Test
    public void testSkip() throws Exception {
        byte[] data = {0x31, 0x32, 0x33, 0x34, 0x35}; // "12345"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        long skipped = stream.skip(2);
        assertEquals(2, skipped);

        byte[] buffer = new byte[3];
        int read = stream.read(buffer, 0, 3);
        assertEquals(3, read);
        assertArrayEquals(new byte[]{0x33, 0x34, 0x35}, buffer);
        stream.close();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSkipWithNegativeLength() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        stream.skip(-1);
    }

    @Test
    public void testResetThrowsIOException() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        try {
            stream.reset();
            fail("Expected IOException");
        } catch (IOException e) {
            assertEquals("mark/reset not supported", e.getMessage());
        }
        stream.close();
    }

    @Test
    public void testMarkDoesNothing() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        stream.mark(100);
        // No exception should be thrown
        stream.close();
    }
}
