    /**

     * Writes the specified {@code byte} to this output stream.

     *

     * @param i source byte.

     * @throws IOException Thrown if an I/O error occurs.

     */

    @Override

    public void write(final int i) throws IOException {

        singleByte[0] = (byte) i;

        write(singleByte, 0, 1);

    }

}

