    @Test
    public void testBuilder() {
        Crc16.Builder builder = Crc16.builder();
        assertNotNull(builder);
    }

    @Test
    public void testBuilderSetInit() {
        Crc16.Builder builder = Crc16.builder().setInit(0x1234);
        Crc16 crc16 = builder.get();
        assertEquals(0x1234, crc16.init);
    }

    @Test
    public void testBuilderSetTable() {
        int[] customTable = {0x0000, 0x1111};
        Crc16.Builder builder = Crc16.builder().setTable(customTable);
        Crc16 crc16 = builder.get();
        assertArrayEquals(customTable, crc16.table);
    }

