                throw new IllegalArgumentException("Invalid prefix value: " + prefix);

            }

            final Pattern p = Pattern.compile("^" + prefix.replace("$", "\\$") + "([\\.\\/a-zA-Z0-9]{1,8}).*");

            final Matcher m = p.matcher(salt);

            if (!m.find()) {

