     * @param offset The first element of array.

     * @param length The length of array.

     * @param seed The initial seed value.

     * @return The 128-bit hash (2 longs).

     */

    private static long[] hash128x64Internal(final byte[] data, final int offset, final int length, final long seed) {

        long h1 = seed;

        long h2 = seed;

        final int nblocks = length >> 4;

        // body

        for (int i = 0; i < nblocks; i++) {

            final int index = offset + (i << 4);

            long k1 = MurmurHash.getLittleEndianLong(data, index);

            long k2 = MurmurHash.getLittleEndianLong(data, index + 8);

            // mix functions for k1

            k1 *= C1;

            k1 = Long.rotateLeft(k1, R1);

            k1 *= C2;

            h1 ^= k1;

            h1 = Long.rotateLeft(h1, R2);

            h1 += h2;

            h1 = h1 * M + N1;

            // mix functions for k2

            k2 *= C2;

            k2 = Long.rotateLeft(k2, R3);

            k2 *= C1;

            h2 ^= k2;

            h2 = Long.rotateLeft(h2, R1);

            h2 += h1;

            h2 = h2 * M + N2;

        }

        // tail

        long k1 = 0;

        long k2 = 0;

        final int index = offset + (nblocks << 4);

        switch (offset + length - index) {

        case 15:

            k2 ^= ((long) data[index + 14] & 0xff) << 48;

            // falls-through

        case 14:

            k2 ^= ((long) data[index + 13] & 0xff) << 40;

            // falls-through

        case 13:

            k2 ^= ((long) data[index + 12] & 0xff) << 32;

            // falls-through

        case 12:

            k2 ^= ((long) data[index + 11] & 0xff) << 24;

            // falls-through

        case 11:

            k2 ^= ((long) data[index + 10] & 0xff) << 16;

            // falls-through

        case 10:

            k2 ^= ((long) data[index + 9] & 0xff) << 8;

            // falls-through

        case 9:

            k2 ^= data[index + 8] & 0xff;

            k2 *= C2;

            k2 = Long.rotateLeft(k2, R3);

            k2 *= C1;

            h2 ^= k2;

            // falls-through

        case 8:

            k1 ^= ((long) data[index + 7] & 0xff) << 56;

            // falls-through

        case 7:

            k1 ^= ((long) data[index + 6] & 0xff) << 48;

            // falls-through

        case 6:

            k1 ^= ((long) data[index + 5] & 0xff) << 40;

            // falls-through

        case 5:

            k1 ^= ((long) data[index + 4] & 0xff) << 32;

            // falls-through

        case 4:

            k1 ^= ((long) data[index + 3] & 0xff) << 24;

            // falls-through

        case 3:

            k1 ^= ((long) data[index + 2] & 0xff) << 16;

            // falls-through

        case 2:

            k1 ^= ((long) data[index + 1] & 0xff) << 8;

            // falls-through

        case 1:

            k1 ^= data[index] & 0xff;

            k1 *= C1;

            k1 = Long.rotateLeft(k1, R1);

            k1 *= C2;

            h1 ^= k1;

        }

        // finalization

        h1 ^= length;

        h2 ^= length;



        h1 += h2;

        h2 += h1;



        h1 = fmix64(h1);

        h2 = fmix64(h2);



        h1 += h2;

        h2 += h1;

        return new long[] { h1, h2 };

    }



