package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class PureJavaCrc32CTest {

    @Test
    public void testReset() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        crc.reset();
        assertEquals(0xFFFFFFFFL, crc.getValue());
    }

    @Test
    public void testUpdateByteArray() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] testData = "Hello, World!".getBytes();
        crc.update(testData, 0, testData.length);
        assertEquals(0xC400993DL, crc.getValue());
    }

    @Test
    public void testUpdateByteArrayWithOffset() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] testData = "Hello, World!".getBytes();
        crc.update(testData, 7, 5); // "World"
        assertEquals(0x57575757L, crc.getValue());
    }

    @Test
    public void testUpdateByteArrayEmpty() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] emptyData = new byte[0];
        crc.update(emptyData, 0, 0);
        assertEquals(0xFFFFFFFFL, crc.getValue());
    }

    @Test
    public void testUpdateByteArraySingleByte() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] singleByte = new byte[]{'A'};
        crc.update(singleByte, 0, 1);
        assertEquals(0xFEFEFEFEL, crc.getValue());
    }

    @Test
    public void testUpdateByteArrayMultipleUpdates() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] part1 = "Hello".getBytes();
        byte[] part2 = ", World!".getBytes();

        crc.update(part1, 0, part1.length);
        crc.update(part2, 0, part2.length);
        assertEquals(0xC400993DL, crc.getValue());
    }

    @Test
    public void testUpdateInt() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        crc.update('A');
        assertEquals(0xFEFEFEFEL, crc.getValue());
    }

    @Test
    public void testUpdateIntMultiple() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        crc.update('H');
        crc.update('e');
        crc.update('l');
        crc.update('l');
        crc.update('o');
        assertEquals(0xFEFEFEFEL, crc.getValue());
    }

    @Test
    public void testUpdateIntAndByteArray() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        crc.update('H');
        byte[] rest = "ello, World!".getBytes();
        crc.update(rest, 0, rest.length);
        assertEquals(0xC400993DL, crc.getValue());
    }

    @Test
    public void testUpdateByteArrayWithNull() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        try {
            crc.update(null, 0, 0);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertTrue(true);
        }
    }

    @Test
    public void testUpdateByteArrayWithNegativeLength() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] testData = "Hello, World!".getBytes();
        try {
            crc.update(testData, 0, -1);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(true);
        }
    }

    @Test
    public void testUpdateByteArrayWithInvalidOffset() {
        PureJavaCrc32C crc = new PureJavaCrc32C();
        byte[] testData = "Hello, World!".getBytes();
        try {
            crc.update(testData, 100, 5);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            assertTrue(true);
        }
    }
}
