         * Create byte sequence P.

         */

        final byte[] bytes = new byte[keyLen];

        int cp = 0;

        while (cp < keyLen - blocksize) {

            System.arraycopy(tempResult, 0, bytes, cp, blocksize);

            cp += blocksize;

        }

        System.arraycopy(tempResult, 0, bytes, cp, keyLen - cp);



