            for (int i = 0; i < 32; i += 4) {

                left = dEncrypt(left, right, i, eSwap0, eSwap1, schedule);

                right = dEncrypt(right, left, i + 2, eSwap0, eSwap1, schedule);

            }

            t = left;

            left = right;

            right = t;

