package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class UnixCryptTest {

    @Test
    public void testCryptWithNullSalt() {
        String password = "password";
        String hashed = UnixCrypt.crypt(password.getBytes());
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
        assertTrue(hashed.matches("^[a-zA-Z0-9./]{2}.*$"));
    }

    @Test
    public void testCryptWithValidSalt() {
        String password = "password";
        String salt = "ab";
        String hashed = UnixCrypt.crypt(password.getBytes(), salt);
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
        assertTrue(hashed.startsWith(salt));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCryptWithInvalidSalt() {
        String password = "password";
        String invalidSalt = "xy"; // Not in allowed character set
        UnixCrypt.crypt(password.getBytes(), invalidSalt);
    }

    @Test
    public void testCryptWithEmptyPassword() {
        String password = "";
        String hashed = UnixCrypt.crypt(password.getBytes());
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
    }

    @Test
    public void testCryptWithLongPassword() {
        String password = "ThisIsALongPasswordThatShouldBeTruncatedTo8Bytes";
        String hashed = UnixCrypt.crypt(password.getBytes());
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
    }

    @Test
    public void testCryptWithStringInput() {
        String password = "password";
        String hashed = UnixCrypt.crypt(password);
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
    }

    @Test
    public void testCryptWithStringInputAndSalt() {
        String password = "password";
        String salt = "ab";
        String hashed = UnixCrypt.crypt(password, salt);
        assertNotNull(hashed);
        assertEquals(13, hashed.length());
        assertTrue(hashed.startsWith(salt));
    }

    @Test
    public void testConsistentHashing() {
        String password = "password";
        String salt = "ab";
        String hashed1 = UnixCrypt.crypt(password.getBytes(), salt);
        String hashed2 = UnixCrypt.crypt(password.getBytes(), salt);
        assertEquals(hashed1, hashed2);
    }

    @Test
    public void testDifferentSaltsProduceDifferentHashes() {
        String password = "password";
        String hashed1 = UnixCrypt.crypt(password.getBytes(), "ab");
        String hashed2 = UnixCrypt.crypt(password.getBytes(), "cd");
        assertNotEquals(hashed1, hashed2);
    }

    @Test
    public void testDifferentPasswordsProduceDifferentHashes() {
        String hashed1 = UnixCrypt.crypt("password1".getBytes(), "ab");
        String hashed2 = UnixCrypt.crypt("password2".getBytes(), "ab");
        assertNotEquals(hashed1, hashed2);
    }
