        txt = txt.replace("cq", "2q");

        txt = txt.replace("ci", "si");

        txt = txt.replace("ce", "se");

        txt = txt.replace("cy", "sy");

        txt = txt.replace("tch", "2ch");

        txt = txt.replace("c", "k");

