 * <th>Context</th>

 * <th>Code</th>

 * </tr>

 * <tr>

 * <td>A, E, I, J, O, U, Y</td>

 * <td></td>

 * <td>0</td>

 * </tr>

 * <tr>

 *

 * <td>H</td>

 * <td></td>

 * <td>-</td>

 * </tr>

 * <tr>

 * <td>B</td>

 * <td></td>

 * <td rowspan="2">1</td>

 * </tr>

 * <tr>

 * <td>P</td>

 * <td>not before H</td>

 *

 * </tr>

 * <tr>

 * <td>D, T</td>

 * <td>not before C, S, Z</td>

 * <td>2</td>

 * </tr>

 * <tr>

 * <td>F, V, W</td>

 * <td></td>

 * <td rowspan="2">3</td>

 * </tr>

 * <tr>

 *

 * <td>P</td>

 * <td>before H</td>

 * </tr>

 * <tr>

 * <td>G, K, Q</td>

 * <td></td>

 * <td rowspan="3">4</td>

 * </tr>

 * <tr>

 * <td rowspan="2">C</td>

 * <td>at onset before A, H, K, L, O, Q, R, U, X</td>

 *

 * </tr>

