 * <tr>

 * <td>not before A, H, K, O, Q, U, X</td>

 * </tr>

 * <tr>

 * <td>D, T</td>

 * <td>before C, S, Z</td>

 * </tr>

 * <tr>

 * <td>X</td>

 * <td>after C, K, Q</td>

 * </tr>

 * </tbody>

 * </table>

