 * </tr>

 * <tr>

 * <td>F, V, W</td>

 * <td></td>

 * <td rowspan="2">3</td>

 * </tr>

 * <tr>

 *

 * <td>P</td>

 * <td>before H</td>

 * </tr>

 * <tr>

 * <td>G, K, Q</td>

 * <td></td>

 * <td rowspan="3">4</td>

 * </tr>

 * <tr>

 * <td rowspan="2">C</td>

 * <td>at onset before A, H, K, L, O, Q, R, U, X</td>

 *

