            if (contains(value, index, 3, "CIO", "CIE", "CIA")) {

                result.append('S', 'X');

            } else {

                result.append('S');

            }

            index += 2;

        } else {

            result.append('K');

            if (contains(value, index + 1, 2, " C", " Q", " G")) {

                //-- Mac Caffrey, Mac Gregor --//

                index += 3;

            } else if (contains(value, index + 1, 1, "C", "K", "Q") &&

                       !contains(value, index + 1, 2, "CE", "CI")) {

                index += 2;

            } else {

                index++;

            }

        }



        return index;

    }



    /**

     * Handles 'CC' cases.

     */

    private int handleCC(final String value, final DoubleMetaphoneResult result, int index) {

        if (contains(value, index + 2, 1, "I", "E", "H") &&

            !contains(value, index + 2, 2, "HU")) {

            //-- "bellocchio" but not "bacchus" --//

            if (index == 1 && charAt(value, index - 1) == 'A' ||

                contains(value, index - 1, 5, "UCCEE", "UCCES")) {

                //-- "accident", "accede", "succeed" --//

                result.append("KS");

            } else {

                //-- "bacci", "bertucci", other Italian --//

                result.append('X');

            }

            index += 3;

        } else {    // Pierce's rule

            result.append('K');

            index += 2;

        }



        return index;

    }



    /**

     * Handles 'CH' cases.

     */

    private int handleCH(final String value, final DoubleMetaphoneResult result, final int index) {

        if (index > 0 && contains(value, index, 4, "CHAE")) {   // Michael

            result.append('K', 'X');

            return index + 2;

        }

        if (conditionCH0(value, index)) {

            //-- Greek roots ("chemistry", "chorus", etc.) --//

            result.append('K');

            return index + 2;

        }

        if (conditionCH1(value, index)) {

            //-- Germanic, Greek, or otherwise 'ch' for 'kh' sound --//

            result.append('K');

            return index + 2;

        }

        if (index > 0) {

            if (contains(value, 0, 2, "MC")) {

                result.append('K');

            } else {

                result.append('X', 'K');

            }

        } else {

            result.append('X');

        }

        return index + 2;

    }



    /**

     * Handles 'D' cases.

