                   contains(value, index - 1, 4, "AGGI", "OGGI")) {

            //-- Italian "biaggi" --//

            if (contains(value, 0, 4, "VAN ", "VON ") ||

                contains(value, 0, 3, "SCH") ||

                contains(value, index + 1, 2, "ET")) {

                //-- obvious germanic --//

                result.append('K');

            } else if (contains(value, index + 1, 3, "IER")) {

                result.append('J');

            } else {

                result.append('J', 'K');

            }

            index += 2;

        } else {

            if (charAt(value, index + 1) == 'G') {

                index += 2;

            } else {

                index++;

            }

            result.append('K');

        }

        return index;

    }



    /**

     * Handles 'GH' cases.

     */

    private int handleGH(final String value, final DoubleMetaphoneResult result, int index) {

        if (index > 0 && !isVowel(charAt(value, index - 1))) {

            result.append('K');

            index += 2;

        } else if (index == 0) {

            if (charAt(value, index + 2) == 'I') {

                result.append('J');

            } else {

                result.append('K');

            }

            index += 2;

        } else if (index > 1 && contains(value, index - 2, 1, "B", "H", "D") ||

                   index > 2 && contains(value, index - 3, 1, "B", "H", "D") ||

                   index > 3 && contains(value, index - 4, 1, "B", "H")) {

            //-- Parker's rule (with some further refinements) - "hugh"

            index += 2;

        } else {

            if (index > 2 && charAt(value, index - 1) == 'U' &&

                contains(value, index - 3, 1, "C", "G", "L", "R", "T")) {

                //-- "laugh", "McLaughlin", "cough", "gough", "rough", "tough"

                result.append('F');

            } else if (index > 0 && charAt(value, index - 1) != 'I') {

                result.append('K');

            }

            index += 2;

        }

        return index;

    }



    /**

     * Handles 'H' cases.

     */

    private int handleH(final String value, final DoubleMetaphoneResult result, int index) {

        //-- only keep if first & before vowel or between 2 vowels --//

        if ((index == 0 || isVowel(charAt(value, index - 1))) &&

            isVowel(charAt(value, index + 1))) {

            result.append('H');

            index += 2;

            //-- also takes car of "HH" --//

        } else {

            index++;

        }

        return index;

    }



    /**

