    private int handleSC(final String value, final DoubleMetaphoneResult result, final int index) {

        if (charAt(value, index + 2) == 'H') {

            //-- Schlesinger's rule --//

            if (contains(value, index + 3, 2, "OO", "ER", "EN", "UY", "ED", "EM")) {

