                contains(value, 0, 3, "SCH")) {

                result.append('T');

            } else {

                result.append('0', 'T');

            }

            index += 2;

        } else {

            result.append('T');

            index = contains(value, index + 1, 1, "T", "D") ? index + 2 : index + 1;

        }

        return index;

    }



    /**

     * Handles 'W' cases.

     */

