    String cleanName(final String name) {

        String upperName = name.toUpperCase(Locale.ENGLISH);



        final String[] charsToTrim = { "\\-", "[&]", "\\'", "\\.", "[\\,]" };

        for (final String str : charsToTrim) {

            upperName = upperName.replaceAll(str, EMPTY);

