package org.apache.commons.codec.language;

import org.apache.commons.codec.EncoderException;
import org.junit.Test;
import static org.junit.Assert.*;

public class MetaphoneTest {

    @Test
    public void testEncodeObjectWithNonStringInput() {
        Metaphone metaphone = new Metaphone();
        try {
            metaphone.encode(123);
            fail("Expected EncoderException");
        } catch (EncoderException e) {
            assertEquals("Parameter supplied to Metaphone encode is not of type java.lang.String", e.getMessage());
        }
    }

    @Test
    public void testEncodeObjectWithStringInput() throws EncoderException {
        Metaphone metaphone = new Metaphone();
        String input = "Hello";
        String expected = metaphone.encode(input);
        assertEquals(expected, metaphone.encode((Object) input));
    }

    @Test
    public void testEncodeWithEmptyString() {
        Metaphone metaphone = new Metaphone();
        assertEquals("", metaphone.encode(""));
    }

    @Test
    public void testEncodeWithSingleCharacter() {
        Metaphone metaphone = new Metaphone();
        assertEquals("A", metaphone.encode("a"));
        assertEquals("B", metaphone.encode("b"));
        assertEquals("Z", metaphone.encode("z"));
    }

    @Test
    public void testEncodeWithCommonWords() {
        Metaphone metaphone = new Metaphone();
        assertEquals("HL", metaphone.encode("Hello"));
        assertEquals("KL", metaphone.encode("Kyle"));
        assertEquals("NT", metaphone.encode("Night"));
        assertEquals("L", metaphone.encode("Love"));
    }

    @Test
    public void testEncodeWithSpecialCases() {
        Metaphone metaphone = new Metaphone();
        assertEquals("S", metaphone.encode("Xylophone"));
        assertEquals("K", metaphone.encode("Knife"));
        assertEquals("W", metaphone.encode("Whale"));
        assertEquals("S", metaphone.encode("Sugar"));
    }

    @Test
    public void testIsMetaphoneEqual() {
        Metaphone metaphone = new Metaphone();
        assertTrue(metaphone.isMetaphoneEqual("Hello", "Halo"));
        assertFalse(metaphone.isMetaphoneEqual("Hello", "World"));
        assertTrue(metaphone.isMetaphoneEqual("", ""));
    }

    @Test
    public void testGetAndSetMaxCodeLen() {
        Metaphone metaphone = new Metaphone();
        assertEquals(4, metaphone.getMaxCodeLen());
        metaphone.setMaxCodeLen(5);
        assertEquals(5, metaphone.getMaxCodeLen());
    }

    @Test
    public void testMetaphoneWithMaxCodeLen() {
        Metaphone metaphone = new Metaphone();
        metaphone.setMaxCodeLen(3);
        assertEquals("HL", metaphone.encode("Hello"));
        assertEquals("KL", metaphone.encode("Kyle"));
    }

    @Test
    public void testMetaphoneWithLongWord() {
        Metaphone metaphone = new Metaphone();
        assertEquals("NT", metaphone.encode("Nightingale"));
        assertEquals("L", metaphone.encode("Elephant"));
    }
}
