        str = SoundexUtils.clean(str);

        if (str.isEmpty()) {

            return str;

        }

        final char[] out = { '0', '0', '0', '0' };

        int count = 0;

        final char first = str.charAt(0);

        out[count++] = first;

        char lastDigit = map(first); // previous digit

        for (int i = 1; i < str.length() && count < out.length; i++) {

            final char ch = str.charAt(i);

