package org.apache.commons.codec.language;

import org.apache.commons.codec.EncoderException;
import org.junit.Test;
import static org.junit.Assert.*;

public class SoundexTest {

    @Test
    public void testSoundexWithNullInput() {
        Soundex soundex = new Soundex();
        assertNull(soundex.soundex(null));
    }

    @Test
    public void testSoundexWithEmptyString() {
        Soundex soundex = new Soundex();
        assertEquals("", soundex.soundex(""));
    }

    @Test
    public void testSoundexWithSingleCharacter() {
        Soundex soundex = new Soundex();
        assertEquals("A000", soundex.soundex("A"));
        assertEquals("B000", soundex.soundex("B"));
        assertEquals("C000", soundex.soundex("C"));
    }

    @Test
    public void testSoundexWithCommonNames() {
        Soundex soundex = new Soundex();
        assertEquals("S530", soundex.soundex("Smith"));
        assertEquals("S530", soundex.soundex("Smythe"));
        assertEquals("S530", soundex.soundex("Smyth"));
        assertEquals("S530", soundex.soundex("Smithe"));
        assertEquals("S530", soundex.soundex("Smythee"));
        assertEquals("S530", soundex.soundex("Smytheee"));
    }

    @Test
    public void testSoundexWithSpecialCharacters() {
        Soundex soundex = new Soundex();
        assertEquals("S530", soundex.soundex("Smith!"));
        assertEquals("S530", soundex.soundex("Smith@"));
        assertEquals("S530", soundex.soundex("Smith#"));
        assertEquals("S530", soundex.soundex("Smith$"));
        assertEquals("S530", soundex.soundex("Smith%"));
    }

    @Test
    public void testSoundexWithHAndW() {
        Soundex soundex = new Soundex();
        assertEquals("H000", soundex.soundex("H"));
        assertEquals("W000", soundex.soundex("W"));
        assertEquals("H450", soundex.soundex("Helen"));
        assertEquals("W450", soundex.soundex("William"));
    }

    @Test
    public void testSoundexWithVowels() {
        Soundex soundex = new Soundex();
        assertEquals("A000", soundex.soundex("A"));
        assertEquals("E000", soundex.soundex("E"));
        assertEquals("I000", soundex.soundex("I"));
        assertEquals("O000", soundex.soundex("O"));
        assertEquals("U000", soundex.soundex("U"));
        assertEquals("A400", soundex.soundex("Apple"));
    }

    @Test
    public void testSoundexWithDifferentCases() {
        Soundex soundex = new Soundex();
        assertEquals("S530", soundex.soundex("Smith"));
        assertEquals("S530", soundex.soundex("SMITH"));
        assertEquals("S530", soundex.soundex("smitH"));
        assertEquals("S530", soundex.soundex("sMiTh"));
    }

    @Test
    public void testSoundexWithCustomMapping() {
        char[] customMapping = "01230120022455012623010202".toCharArray();
        Soundex soundex = new Soundex(customMapping);
        assertEquals("S530", soundex.soundex("Smith"));
    }

    @Test
    public void testSoundexWithSpecialCaseHWDisabled() {
        Soundex soundex = new Soundex(Soundex.US_ENGLISH_MAPPING_STRING, false);
        assertEquals("H450", soundex.soundex("Helen"));
        assertEquals("W450", soundex.soundex("William"));
    }

    @Test
    public void testEncodeObject() throws EncoderException {
        Soundex soundex = new Soundex();
        assertEquals("S530", soundex.encode("Smith"));
        try {
            soundex.encode(123);
            fail("Expected EncoderException");
        } catch (EncoderException e) {
            assertEquals("Parameter supplied to Soundex encode is not of type java.lang.String", e.getMessage());
        }
    }

    @Test
    public void testDifference() throws EncoderException {
        Soundex soundex = new Soundex();
        assertEquals(4, soundex.difference("Smith", "Smith"));
        assertEquals(3, soundex.difference("Smith", "Smythe"));
        assertEquals(2, soundex.difference("Smith", "Smyth"));
        assertEquals(1, soundex.difference("Smith", "Smithe"));
        assertEquals(0, soundex.difference("Smith", "Smythee"));
    }

    @Test
    public void testSoundexWithUnmappedCharacter() {
        Soundex soundex = new Soundex();
        try {
            soundex.soundex("Z");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The character is not mapped: Z (index=25)", e.getMessage());
        }
    }
}
