    public void testEncodeSimpleWord() {
        BeiderMorseEncoder encoder = new BeiderMorseEncoder();
        assertEquals("rYnDlt|rYnalt|rYnult|rinDlt|rinalt|rinult", encoder.encode("Renault"));
    }

    @Test
    public void testEncodeHyphenatedWord() {
        BeiderMorseEncoder encoder = new BeiderMorseEncoder();
        assertEquals("(ortlaj|ortlej)-(dortlaj|dortlej)", encoder.encode("d'ortley"));
    }

