@RunWith(MockitoJUnitRunner.class)
public class LangTest {

    private Lang lang;

    @Mock
    private Languages languages;

    @Before
    public void setUp() {
        lang = Lang.instance(NameType.GENERIC);
    }

    @Test
    public void testInstance() {
        assertEquals(NameType.GENERIC, lang.guessLanguage("test").toLowerCase());
    }

    @Test
    public void testGuessLanguageWithSingleMatch() {
        assertEquals("english", lang.guessLanguage("hello"));
    }

    @Test
    public void testGuessLanguageWithNoMatch() {
        assertEquals(Languages.ANY, lang.guessLanguage("xyz123"));
    }

    @Test
    public void testGuessLanguageWithMultipleMatches() {
        assertEquals(Languages.ANY, lang.guessLanguage("cafe"));
    }

    @Test
    public void testGuessLanguagesWithSingleMatch() {
