        assertEquals(expected, lang.guessLanguages("hello").getLanguages());
    }

    @Test
    public void testGuessLanguagesWithNoMatch() {
        assertTrue(lang.guessLanguages("xyz123").isEmpty());
    }

    @Test
    public void testGuessLanguagesWithMultipleMatches() {
        Set<String> expected = new HashSet<>(Arrays.asList("french", "spanish"));
        assertEquals(expected, lang.guessLanguages("cafe").getLanguages());
    }

    @Test
    public void testLoadFromResource() {
