        }



        @Override

        public boolean isEmpty() {

            return true;

        }



        @Override

        public boolean isSingleton() {

            return false;

        }



        @Override

        public LanguageSet merge(final LanguageSet other) {

            return other;

        }



        @Override

        public LanguageSet restrictTo(final LanguageSet other) {

            return this;

        }



        @Override

        public String toString() {

            return "NO_LANGUAGES";

        }

    };



    /**

     * Any/all languages.

     */

    public static final LanguageSet ANY_LANGUAGE = new LanguageSet() {



        @Override

        public boolean contains(final String language) {

            return true;

        }



        @Override

        public String getAny() {

            throw new NoSuchElementException("Can't fetch any language from the any language set.");

        }



        @Override

        public boolean isEmpty() {

            return false;

        }



        @Override

        public boolean isSingleton() {

            return false;

        }



        @Override

        public LanguageSet merge(final LanguageSet other) {

            return other;

        }



        @Override

        public LanguageSet restrictTo(final LanguageSet other) {

            return other;

        }



