        }



        @Override

        public boolean isSingleton() {

            return false;

        }



        @Override

        public LanguageSet merge(final LanguageSet other) {

            return other;

        }



        @Override

        public LanguageSet restrictTo(final LanguageSet other) {

            return other;

        }



        @Override

        public String toString() {

            return "ANY_LANGUAGE";

        }

    };



