public class PhoneticEngineTest {

    @Test
    public void testConstructorWithDefaultMaxPhonemes() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        assertEquals(20, engine.getMaxPhonemes());
    }

    @Test
    public void testConstructorWithCustomMaxPhonemes() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false, 10);
        assertEquals(10, engine.getMaxPhonemes());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithInvalidRuleType() {
        new PhoneticEngine(NameType.GENERIC, RuleType.RULES, false);
    }

    @Test
    public void testEncodeWithGenericNameType() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        String result = engine.encode("Smith");
        assertNotNull(result);
        assertFalse(result.isEmpty());
    }

    @Test
    public void testEncodeWithAshkenaziNameType() {
        PhoneticEngine engine = new PhoneticEngine(NameType.ASHKENAZI, RuleType.APPROX, false);
        String result = engine.encode("Kowalski");
        assertNotNull(result);
        assertFalse(result.isEmpty());
    }

    @Test
    public void testEncodeWithSephardicNameType() {
        PhoneticEngine engine = new PhoneticEngine(NameType.SEPHARDIC, RuleType.APPROX, false);
        String result = engine.encode("Rodriguez");
        assertNotNull(result);
        assertFalse(result.isEmpty());
    }

    @Test
    public void testEncodeWithMultiWordName() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        String result = engine.encode("John Smith");
        assertNotNull(result);
        assertFalse(result.isEmpty());
    }

    @Test
    public void testEncodeWithPrefix() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        String result = engine.encode("de la Cruz");
        assertNotNull(result);
        assertFalse(result.isEmpty());
    }

    @Test
    public void testEncodeWithEmptyString() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        String result = engine.encode("");
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testEncodeWithNullInput() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        String result = engine.encode(null);
        assertNull(result);
    }

    @Test
    public void testEncodeWithSpecificLanguageSet() {
        PhoneticEngine engine = new PhoneticEngine(NameType.GENERIC, RuleType.APPROX, false);
        Set<String> languages = new HashSet<>(Arrays.asList("english"));
