    public void testPhonemeConstruction() {
        Phoneme phoneme = new Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        assertEquals("test", phoneme.getPhonemeText().toString());
        assertEquals("Languages([en])", phoneme.getLanguages().toString());
    }

    @Test
    public void testPhonemeAppend() {
        Phoneme phoneme = new Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        phoneme.append("ing");
        assertEquals("testing", phoneme.getPhonemeText().toString());
    }

    @Test
    public void testPhonemeJoin() {
        Phoneme phoneme1 = new Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Phoneme phoneme2 = new Phoneme("ing", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Phoneme joined = phoneme1.join(phoneme2);
