        // fail early if any of the evaluations is not successful

        if (!input.subSequence(i, ipl).equals(pattern)) {

            return false;

        }

        if (!rContext.isMatch(input.subSequence(ipl, input.length()))) {

            return false;

        }

        return lContext.isMatch(input.subSequence(0, i));

