        public Phoneme mergeWithLanguage(final LanguageSet lang) {

            return new Phoneme(phonemeText.toString(), languages.merge(lang));

        }



        @Override

        public int size() {

            return 1;

        }



        @Override

        public String toString() {

            return phonemeText.toString() + "[" + languages + "]";

        }

    }



    /**

