package org.apache.commons.codec.language.bm;

import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.apache.commons.codec.language.bm.Languages.LanguageSet;
import org.junit.Test;

public class RuleTest {

    @Test
    public void testPhonemeConstruction() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        assertEquals("test", phoneme.getPhonemeText().toString());
        assertEquals("Languages([en])", phoneme.getLanguages().toString());
    }

    @Test
    public void testPhonemeAppend() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        phoneme.append("ing");
        assertEquals("testing", phoneme.getPhonemeText().toString());
    }

    @Test
    public void testPhonemeJoin() {
        Rule.Phoneme phoneme1 = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule.Phoneme phoneme2 = new Rule.Phoneme("ing", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule.Phoneme joined = phoneme1.join(phoneme2);
        assertEquals("testing", joined.getPhonemeText().toString());
        assertEquals("Languages([en])", joined.getLanguages().toString());
    }

    @Test
    public void testPhonemeMergeWithLanguage() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        LanguageSet newLang = LanguageSet.from(new HashSet<>(Arrays.asList("fr")));
        Rule.Phoneme merged = phoneme.mergeWithLanguage(newLang);
        assertEquals("test", merged.getPhonemeText().toString());
        assertEquals("Languages([en, fr])", merged.getLanguages().toString());
    }

    @Test
    public void testPhonemeListConstruction() {
        Rule.Phoneme phoneme1 = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule.Phoneme phoneme2 = new Rule.Phoneme("ing", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule.PhonemeList phonemeList = new Rule.PhonemeList(Arrays.asList(phoneme1, phoneme2));
        assertEquals(2, phonemeList.size());
        assertEquals(2, phonemeList.getPhonemes().size());
    }

    @Test
    public void testRuleConstruction() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "left", "right", phoneme);
        assertEquals("pat", rule.getPattern());
        assertEquals(phoneme, rule.getPhoneme());
    }

    @Test
    public void testPatternAndContextMatches() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "left", "right", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertFalse(rule.patternAndContextMatches("leftpatright", 3));
        assertFalse(rule.patternAndContextMatches("leftpatright", 5));
    }

    @Test
    public void testParsePhoneme() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        assertEquals("test", phoneme.getPhonemeText().toString());
        assertEquals("Languages([en])", phoneme.getLanguages().toString());
    }

    @Test
    public void testParsePhonemeExprWithOptions() {
        Rule.PhonemeExpr phonemeExpr = Rule.parsePhonemeExpr("(test|ing)");
        List<Rule.Phoneme> phonemes = (List<Rule.Phoneme>) phonemeExpr.getPhonemes();
        assertEquals(2, phonemes.size());
        assertEquals("test", phonemes.get(0).getPhonemeText().toString());
        assertEquals("ing", phonemes.get(1).getPhonemeText().toString());
    }

    @Test
    public void testPatternMatchingExactMatch() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertFalse(rule.patternAndContextMatches("leftpatrightx", 4));
        assertFalse(rule.patternAndContextMatches("xleftpatright", 4));
    }

    @Test
    public void testPatternMatchingWithEmptyPattern() {
        Rule.Phoneme phoneme = new Rule.Phoneme("", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("left", 0));
        assertFalse(rule.patternAndContextMatches("leftx", 0));
    }

    @Test
    public void testPatternMatchingWithEmptyContext() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("patright", 0));
        assertFalse(rule.patternAndContextMatches("xpatright", 0));
    }

    @Test
    public void testPatternMatchingWithBoxPattern() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("[a-z]", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("leftaright", 4));
        assertFalse(rule.patternAndContextMatches("left1right", 4));
    }

    @Test
    public void testPatternMatchingWithNegatedBoxPattern() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("[^a-z]", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("left1right", 4));
        assertFalse(rule.patternAndContextMatches("leftaright", 4));
    }

    @Test
    public void testPatternMatchingWithStartAnchor() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertFalse(rule.patternAndContextMatches("xleftpatright", 4));
    }

    @Test
    public void testPatternMatchingWithEndAnchor() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertFalse(rule.patternAndContextMatches("leftpatrightx", 4));
    }

    @Test
    public void testPatternMatchingWithBothAnchors() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "^left", "right$", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertFalse(rule.patternAndContextMatches("xleftpatright", 4));
        assertFalse(rule.patternAndContextMatches("leftpatrightx", 4));
    }

    @Test
    public void testPatternMatchingWithNoAnchors() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "left", "right", phoneme);
        assertTrue(rule.patternAndContextMatches("leftpatright", 4));
        assertTrue(rule.patternAndContextMatches("xleftpatright", 5));
        assertTrue(rule.patternAndContextMatches("leftpatrightx", 4));
    }

    @Test
    public void testPatternMatchingWithNegativeIndex() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "left", "right", phoneme);
        try {
            rule.patternAndContextMatches("leftpatright", -1);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            assertEquals("Can not match pattern at negative indexes", e.getMessage());
        }
    }

    @Test
    public void testPatternMatchingWithInsufficientSpace() {
        Rule.Phoneme phoneme = new Rule.Phoneme("test", LanguageSet.from(new HashSet<>(Arrays.asList("en"))));
        Rule rule = new Rule("pat", "left", "right", phoneme);
        assertFalse(rule.patternAndContextMatches("leftp", 4));
    }

    @Test
    public void testParsePhonemeExprWithEmptyOption() {
        Rule.PhonemeExpr phonemeExpr = Rule.parsePhonemeExpr("(test|)");
        List<Rule.Phoneme> phonemes = (List<Rule.Phoneme>) phonemeExpr.getPhonemes();
        assertEquals(2, phonemes.size());
        assertEquals("test", phonemes.get(0).getPhonemeText().toString());
        assertEquals("", phonemes.get(1).getPhonemeText().toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParsePhonemeExprWithInvalidFormat() {
        Rule.parsePhonemeExpr("(test|ing");
    }
}
