        BCodec codec = new BCodec(StandardCharsets.ISO_8859_1);
        assertNotNull(codec);
        assertEquals(StandardCharsets.ISO_8859_1, codec.getCharset());
        assertEquals(CodecPolicy.LENIENT, codec.decodingPolicy);
    }

