package org.apache.commons.codec.net;

import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.Test;

import static org.junit.Assert.*;

public class PercentCodecTest {

    @Test
    public void testDefaultConstructor() {
        PercentCodec codec = new PercentCodec();
        assertNotNull(codec);
    }

    @Test
    public void testConstructorWithAlwaysEncodeChars() {
        byte[] alwaysEncodeChars = new byte[]{'a', 'b', 'c'};
        PercentCodec codec = new PercentCodec(alwaysEncodeChars, false);
        assertNotNull(codec);
    }

    @Test
    public void testEncodeNull() throws EncoderException {
        PercentCodec codec = new PercentCodec();
        assertNull(codec.encode((byte[]) null));
    }

    @Test
    public void testEncodeNonByteArray() throws EncoderException {
        PercentCodec codec = new PercentCodec();
        try {
            codec.encode("not a byte array");
            fail("Expected EncoderException");
        } catch (EncoderException e) {
            assertTrue(e.getMessage().contains("cannot be Percent encoded"));
        }
    }

    @Test
    public void testDecodeNull() throws DecoderException {
        PercentCodec codec = new PercentCodec();
        assertNull(codec.decode((byte[]) null));
    }

    @Test
    public void testDecodeNonByteArray() throws DecoderException {
        PercentCodec codec = new PercentCodec();
        try {
            codec.decode("not a byte array");
            fail("Expected DecoderException");
        } catch (DecoderException e) {
            assertTrue(e.getMessage().contains("cannot be Percent decoded"));
        }
    }

    @Test
    public void testEncodeDecodeSimple() throws EncoderException, DecoderException {
        PercentCodec codec = new PercentCodec();
        byte[] input = "test".getBytes();
        byte[] encoded = codec.encode(input);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testEncodeDecodeWithSpecialChars() throws EncoderException, DecoderException {
        PercentCodec codec = new PercentCodec();
        byte[] input = "%&?=+".getBytes();
        byte[] encoded = codec.encode(input);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testEncodeDecodeWithSpaces() throws EncoderException, DecoderException {
        PercentCodec codec = new PercentCodec();
        byte[] input = "a b c".getBytes();
        byte[] encoded = codec.encode(input);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testEncodeDecodeWithPlusForSpace() throws EncoderException, DecoderException {
        PercentCodec codec = new PercentCodec(new byte[]{}, true);
        byte[] input = "a b c".getBytes();
        byte[] encoded = codec.encode(input);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testEncodeDecodeWithCustomAlwaysEncodeChars() throws EncoderException, DecoderException {
        byte[] alwaysEncodeChars = new byte[]{'a', 'b', 'c'};
        PercentCodec codec = new PercentCodec(alwaysEncodeChars, false);
        byte[] input = "abc123".getBytes();
        byte[] encoded = codec.encode(input);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(input, decoded);
    }

    @Test
    public void testDecodeInvalidPercentEncoding() throws DecoderException {
        PercentCodec codec = new PercentCodec();
        byte[] input = "%G".getBytes();
        try {
            codec.decode(input);
            fail("Expected DecoderException");
        } catch (DecoderException e) {
            assertTrue(e.getMessage().contains("Invalid percent decoding"));
        }
    }
}
