        PRINTABLE_CHARS.set(' ');

        PRINTABLE_CHARS.set('!');

        PRINTABLE_CHARS.set('"');

        PRINTABLE_CHARS.set('#');

        PRINTABLE_CHARS.set('$');

        PRINTABLE_CHARS.set('%');

        PRINTABLE_CHARS.set('&');

        PRINTABLE_CHARS.set('\'');

        PRINTABLE_CHARS.set('(');

        PRINTABLE_CHARS.set(')');

        PRINTABLE_CHARS.set('*');

        PRINTABLE_CHARS.set('+');

        PRINTABLE_CHARS.set(',');

        PRINTABLE_CHARS.set('-');

        PRINTABLE_CHARS.set('.');

        PRINTABLE_CHARS.set('/');

        for (int i = '0'; i <= '9'; i++) {

            PRINTABLE_CHARS.set(i);

        }

        PRINTABLE_CHARS.set(':');

        PRINTABLE_CHARS.set(';');

        PRINTABLE_CHARS.set('<');

        PRINTABLE_CHARS.set('>');

        PRINTABLE_CHARS.set('@');

        for (int i = 'A'; i <= 'Z'; i++) {

