package org.apache.commons.codec.net;

import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.binary.StringUtils;
import org.junit.Test;

import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.nio.charset.UnsupportedCharsetException;

import static org.junit.Assert.*;

public class QuotedPrintableCodecTest {

    @Test
    public void testDecodeNull() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertNull(codec.decode((byte[]) null));
        assertNull(codec.decode((String) null));
        assertNull(codec.decode((Object) null));
    }

    @Test
    public void testDecodeEmpty() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertArrayEquals(new byte[0], codec.decode(new byte[0]));
        assertEquals("", codec.decode(""));
    }

    @Test
    public void testDecodeSimple() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] encoded = "Hello World".getBytes(StandardCharsets.UTF_8);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(encoded, decoded);
    }

    @Test
    public void testDecodeWithEscapedChars() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] encoded = "Hello=20World".getBytes(StandardCharsets.UTF_8);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals("Hello World".getBytes(StandardCharsets.UTF_8), decoded);
    }

    @Test
    public void testDecodeWithLineBreaks() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] encoded = "Hello=0D=0AWorld".getBytes(StandardCharsets.UTF_8);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals("Hello\nWorld".getBytes(StandardCharsets.UTF_8), decoded);
    }

    @Test(expected = DecoderException.class)
    public void testDecodeInvalidEncoding() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        codec.decode("Hello=GWorld".getBytes(StandardCharsets.UTF_8));
    }

    @Test
    public void testEncodeNull() {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertNull(codec.encode((byte[]) null));
        assertNull(codec.encode((String) null));
        assertNull(codec.encode((Object) null));
    }

    @Test
    public void testEncodeEmpty() {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertArrayEquals(new byte[0], codec.encode(new byte[0]));
        assertEquals("", codec.encode(""));
    }

    @Test
    public void testEncodeSimple() {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] original = "Hello World".getBytes(StandardCharsets.UTF_8);
        byte[] encoded = codec.encode(original);
        assertArrayEquals(original, encoded);
    }

    @Test
    public void testEncodeWithSpecialChars() {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] original = "Hello=World".getBytes(StandardCharsets.UTF_8);
        byte[] encoded = codec.encode(original);
        assertArrayEquals("Hello=3DWorld".getBytes(StandardCharsets.UTF_8), encoded);
    }

    @Test
    public void testEncodeWithLineBreaks() {
        QuotedPrintableCodec codec = new QuotedPrintableCodec(true);
        byte[] original = "Hello\nWorld".getBytes(StandardCharsets.UTF_8);
        byte[] encoded = codec.encode(original);
        assertArrayEquals("Hello=0D=0AWorld".getBytes(StandardCharsets.UTF_8), encoded);
    }

