import static org.junit.Assert.*;

public class QuotedPrintableCodecTest {

    @Test
    public void testDecodeNull() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertNull(codec.decode((byte[]) null));
        assertNull(codec.decode((String) null));
        assertNull(codec.decode((Object) null));
    }

    @Test
    public void testDecodeEmpty() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        assertArrayEquals(new byte[0], codec.decode(new byte[0]));
        assertEquals("", codec.decode(""));
    }

    @Test
    public void testDecodeSimple() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] encoded = "Hello World".getBytes(StandardCharsets.UTF_8);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(encoded, decoded);
    }

    @Test
    public void testDecodeWithEscapedChars() throws DecoderException {
        QuotedPrintableCodec codec = new QuotedPrintableCodec();
        byte[] encoded = "Hello=20World".getBytes(StandardCharsets.UTF_8);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals("Hello World".getBytes(StandardCharsets.UTF_8), decoded);
    }

