            WWW_FORM_URL_SAFE.set(i);

        }

        // numeric characters

        for (int i = '0'; i <= '9'; i++) {

            WWW_FORM_URL_SAFE.set(i);

        }

        // special chars

        WWW_FORM_URL_SAFE.set('-');

        WWW_FORM_URL_SAFE.set('_');

        WWW_FORM_URL_SAFE.set('.');

        WWW_FORM_URL_SAFE.set('*');

        // blank to be replaced with +

        WWW_FORM_URL_SAFE.set(' ');



        // Create a copy in case anyone (ab)uses it

        WWW_FORM_URL = (BitSet) WWW_FORM_URL_SAFE.clone();

    }



    /**

     * Decodes an array of URL safe 7-bit characters into an array of original bytes. Escaped characters are converted

     * back to their original representation.

     *

     * @param bytes

     *            array of URL safe characters.

     * @return array of original bytes.

     * @throws DecoderException

     *             Thrown if URL decoding is unsuccessful.

     */

    public static final byte[] decodeUrl(final byte[] bytes) throws DecoderException {

        if (bytes == null) {

            return null;

        }

        final ByteArrayOutputStream buffer = new ByteArrayOutputStream();

        for (int i = 0; i < bytes.length; i++) {

            final int b = bytes[i];

            if (b == PLUS_CHAR) {

                buffer.write(' ');

            } else if (b == ESCAPE_CHAR) {

                try {

                    final int u = Utils.digit16(bytes[++i]);

                    final int l = Utils.digit16(bytes[++i]);

                    buffer.write((char) ((u << 4) + l));

                } catch (final ArrayIndexOutOfBoundsException e) {

                    throw new DecoderException("Invalid URL encoding: ", e);

                }

            } else {

                buffer.write(b);

            }

        }

        return buffer.toByteArray();

    }



    /**

     * Encodes an array of bytes into an array of URL safe 7-bit characters. Unsafe characters are escaped.

     * The characters {@code %} and {@code +} are always escaped because {@link #decodeUrl(byte[])}

     * treats them as URL-encoding syntax.

     *

     * @param urlsafe

     *            bitset of characters deemed URL safe, except for {@code %} and {@code +}.

     * @param bytes

     *            array of bytes to convert to URL safe characters.

     * @return array of bytes containing URL safe characters.

     */

    public static final byte[] encodeUrl(BitSet urlsafe, final byte[] bytes) {

        if (bytes == null) {

            return null;

        }

        if (urlsafe == null) {

            urlsafe = WWW_FORM_URL_SAFE;

        }



        final ByteArrayOutputStream buffer = new ByteArrayOutputStream();

        for (final byte c : bytes) {

            int b = c;

            if (b < 0) {

                b = 256 + b;

            }

            if (urlsafe.get(b) && b != ESCAPE_CHAR && b != PLUS_CHAR) {

                if (b == ' ') {

                    b = PLUS_CHAR;

                }

                buffer.write(b);

            } else {

                buffer.write(ESCAPE_CHAR);

                final char hex1 = Utils.hexChar(b >> 4);

                final char hex2 = Utils.hexChar(b);

                buffer.write(hex1);

                buffer.write(hex2);

            }

        }

        return buffer.toByteArray();

    }



